1	package com.example.starter.playout;
2	
3	import org.springframework.dao.DuplicateKeyException;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.core.RowMapper;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	import java.sql.Date;
11	import java.sql.PreparedStatement;
12	import java.sql.Statement;
13	import java.time.LocalDate;
14	import java.util.List;
15	import java.util.Optional;
16	
17	/**
18	 * 播出编排数据访问层。所有时间列均为 UTC 纪元毫秒（BIGINT），业务日为 Asia/Shanghai 日历日。
19	 */
20	@Repository
21	public class PlayoutRepository {
22	
23	    private final JdbcTemplate jdbc;
24	
25	    public PlayoutRepository(JdbcTemplate jdbc) {
26	        this.jdbc = jdbc;
27	    }
28	
29	    /** 素材行。 */
30	    public record AssetRow(String id, long durationMs) {
31	    }
32	
33	    /** 频道行。 */
34	    public record ChannelRow(String id, String fallbackAssetId) {
35	    }
36	
37	    /** 授权行。 */
38	    public record GrantRow(long id, String channelId, String assetId,
39	                           long validFromMs, long validToMs, boolean revoked) {
40	    }
41	
42	    /** 草稿行。 */
43	    public record DraftRow(String channelId, LocalDate businessDay, long version) {
44	    }
45	
46	    /** 草稿片段行。 */
47	    public record SegmentRow(String id, String assetId, long startMs, long endMs) {
48	    }
49	
50	    /** 发布快照行。 */
51	    public record PublicationRow(long id, String channelId, LocalDate businessDay,
52	                                 long publishedVersion, long draftVersion) {
53	    }
54	
55	    /** 发布快照片段行，grantId 为发布时选定的覆盖授权。 */
56	    public record PublicationSegmentRow(long id, long publicationId, String segmentId,
57	                                        String assetId, long grantId,
58	                                        long startMs, long endMs) {
59	    }
60	
61	    /** 幂等请求记录行；responseBody 为 NULL 表示尚未成功完成（同事务回滚后记录不保留）。 */
62	    public record RequestRow(String requestId, String operation, String paramsHash,
63	                             String responseBody) {
64	    }
65	
66	    /** 紧急插播行；status 为 ACTIVE / CANCELLED，grantId 始终保留创建时指定的原授权关联。 */
67	    public record OverrideRow(String overrideKey, String channelId, String assetId, long grantId,
68	                              int priority, long startMs, long endMs, LocalDate businessDay,
69	                              String status, String cancelRequestId, Long cancelledAtMs,
70	                              long createdAtMs) {
71	        public boolean active() {
72	            return "ACTIVE".equals(status);
73	        }
74	    }
75	
76	    private static final RowMapper<AssetRow> ASSET_MAPPER = (rs, n) ->
77	            new AssetRow(rs.getString("id"), rs.getLong("duration_ms"));
78	
79	    private static final RowMapper<ChannelRow> CHANNEL_MAPPER = (rs, n) ->
80	            new ChannelRow(rs.getString("id"), rs.getString("fallback_asset_id"));
81	
82	    private static final RowMapper<GrantRow> GRANT_MAPPER = (rs, n) ->
83	            new GrantRow(rs.getLong("id"), rs.getString("channel_id"), rs.getString("asset_id"),
84	                    rs.getLong("valid_from_ms"), rs.getLong("valid_to_ms"), rs.getBoolean("revoked"));
85	
86	    private static final RowMapper<DraftRow> DRAFT_MAPPER = (rs, n) ->
87	            new DraftRow(rs.getString("channel_id"), rs.getDate("business_day").toLocalDate(),
88	                    rs.getLong("version"));
89	
90	    private static final RowMapper<SegmentRow> SEGMENT_MAPPER = (rs, n) ->
91	            new SegmentRow(rs.getString("id"), rs.getString("asset_id"),
92	                    rs.getLong("start_ms"), rs.getLong("end_ms"));
93	
94	    private static final RowMapper<PublicationRow> PUBLICATION_MAPPER = (rs, n) ->
95	            new PublicationRow(rs.getLong("id"), rs.getString("channel_id"),
96	                    rs.getDate("business_day").toLocalDate(),
97	                    rs.getLong("published_version"), rs.getLong("draft_version"));
98	
99	    private static final RowMapper<PublicationSegmentRow> PUBLICATION_SEGMENT_MAPPER = (rs, n) ->
100	            new PublicationSegmentRow(rs.getLong("id"), rs.getLong("publication_id"),
101	                    rs.getString("segment_id"), rs.getString("asset_id"), rs.getLong("grant_id"),
102	                    rs.getLong("start_ms"), rs.getLong("end_ms"));
103	
104	    private static final RowMapper<RequestRow> REQUEST_MAPPER = (rs, n) ->
105	            new RequestRow(rs.getString("request_id"), rs.getString("operation"),
106	                    rs.getString("params_hash"), rs.getString("response_body"));
107	
108	    private static final RowMapper<OverrideRow> OVERRIDE_MAPPER = (rs, n) ->
109	            new OverrideRow(rs.getString("override_key"), rs.getString("channel_id"),
110	                    rs.getString("asset_id"), rs.getLong("grant_id"), rs.getInt("priority"),
111	                    rs.getLong("start_ms"), rs.getLong("end_ms"),
112	                    rs.getDate("business_day").toLocalDate(), rs.getString("status"),
113	                    rs.getString("cancel_request_id"),
114	                    (Long) rs.getObject("cancelled_at_ms"), rs.getLong("created_at_ms"));
115	
116	    // ---------- 素材 ----------
117	
118	    public void insertAsset(String id, long durationMs, long createdAtMs) {
119	        jdbc.update("INSERT INTO playout_asset (id, duration_ms, created_at_ms) VALUES (?, ?, ?)",
120	                id, durationMs, createdAtMs);
121	    }
122	
123	    public Optional<AssetRow> findAsset(String id) {
124	        return jdbc.query("SELECT id, duration_ms FROM playout_asset WHERE id = ?",
125	                ASSET_MAPPER, id).stream().findFirst();
126	    }
127	
128	    // ---------- 频道 ----------
129	
130	    public void insertChannel(String id, String fallbackAssetId, long createdAtMs) {
131	        jdbc.update("INSERT INTO playout_channel (id, fallback_asset_id, created_at_ms) VALUES (?, ?, ?)",
132	                id, fallbackAssetId, createdAtMs);
133	    }
134	
135	    public Optional<ChannelRow> findChannel(String id) {
136	        return jdbc.query("SELECT id, fallback_asset_id FROM playout_channel WHERE id = ?",
137	                CHANNEL_MAPPER, id).stream().findFirst();
138	    }
139	
140	    // ---------- 授权 ----------
141	
142	    public long insertGrant(String channelId, String assetId, long validFromMs, long validToMs,
143	                            long createdAtMs) {
144	        KeyHolder keyHolder = new GeneratedKeyHolder();
145	        jdbc.update(con -> {
146	            PreparedStatement ps = con.prepareStatement(
147	                    "INSERT INTO playout_grant (channel_id, asset_id, valid_from_ms, valid_to_ms, created_at_ms)"
148	                            + " VALUES (?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
149	            ps.setString(1, channelId);
150	            ps.setString(2, assetId);
151	            ps.setLong(3, validFromMs);
152	            ps.setLong(4, validToMs);
153	            ps.setLong(5, createdAtMs);
154	            return ps;
155	        }, keyHolder);
156	        return keyHolder.getKey().longValue();
157	    }
158	
159	    public Optional<GrantRow> findGrant(long id) {
160	        return jdbc.query("SELECT id, channel_id, asset_id, valid_from_ms, valid_to_ms, revoked"
161	                + " FROM playout_grant WHERE id = ?", GRANT_MAPPER, id).stream().findFirst();
162	    }
163	
164	    /** 按 ID 查询授权并加行锁，用于紧急插播创建与授权撤销按提交顺序串行化。 */
165	    public Optional<GrantRow> findGrantForUpdate(long id) {
166	        return jdbc.query("SELECT id, channel_id, asset_id, valid_from_ms, valid_to_ms, revoked"
167	                + " FROM playout_grant WHERE id = ? FOR UPDATE", GRANT_MAPPER, id)
168	                .stream().findFirst();
169	    }
170	
171	    /** 撤销授权；返回受影响行数，0 表示不存在或已撤销。 */
172	    public int revokeGrant(long id, String revokeRequestId, long revokedAtMs) {
173	        return jdbc.update("UPDATE playout_grant SET revoked = 1, revoke_request_id = ?, revoked_at_ms = ?"
174	                + " WHERE id = ? AND revoked = 0", revokeRequestId, revokedAtMs, id);
175	    }
176	
177	    /** 查找完整覆盖 [startMs, endMs) 的未撤销授权（区间左闭右开）。 */
178	    public List<GrantRow> findCoveringGrants(String channelId, String assetId,
179	                                             long startMs, long endMs) {
180	        return jdbc.query("SELECT id, channel_id, asset_id, valid_from_ms, valid_to_ms, revoked"
181	                        + " FROM playout_grant"
182	                        + " WHERE channel_id = ? AND asset_id = ? AND revoked = 0"
183	                        + " AND valid_from_ms <= ? AND valid_to_ms >= ?",
184	                GRANT_MAPPER, channelId, assetId, startMs, endMs);
185	    }
186	
187	    /** 同上，但加行锁（FOR UPDATE），用于发布时与撤销串行化。 */
188	    public List<GrantRow> findCoveringGrantsForUpdate(String channelId, String assetId,
189	                                                      long startMs, long endMs) {
190	        return jdbc.query("SELECT id, channel_id, asset_id, valid_from_ms, valid_to_ms, revoked"
191	                        + " FROM playout_grant"
192	                        + " WHERE channel_id = ? AND asset_id = ?"
193	                        + " AND valid_from_ms <= ? AND valid_to_ms >= ?"
194	                        + " ORDER BY id FOR UPDATE",
195	                GRANT_MAPPER, channelId, assetId, startMs, endMs);
196	    }
197	
198	    // ---------- 草稿 ----------
199	
200	    public Optional<DraftRow> findDraft(String channelId, LocalDate businessDay) {
201	        return jdbc.query("SELECT channel_id, business_day, version FROM playout_draft"
202	                        + " WHERE channel_id = ? AND business_day = ?",
203	                DRAFT_MAPPER, channelId, Date.valueOf(businessDay)).stream().findFirst();
204	    }
205	
206	    public void insertDraft(String channelId, LocalDate businessDay, long updatedAtMs) {
207	        jdbc.update("INSERT INTO playout_draft (channel_id, business_day, version, updated_at_ms)"
208	                        + " VALUES (?, ?, 1, ?)",
209	                channelId, Date.valueOf(businessDay), updatedAtMs);
210	    }
211	
212	    /** 乐观锁递增草稿版本；返回受影响行数，0 表示版本冲突或不存在。 */
213	    public int bumpDraftVersion(String channelId, LocalDate businessDay,
214	                                long expectedVersion, long updatedAtMs) {
215	        return jdbc.update("UPDATE playout_draft SET version = version + 1, updated_at_ms = ?"
216	                        + " WHERE channel_id = ? AND business_day = ? AND version = ?",
217	                updatedAtMs, channelId, Date.valueOf(businessDay), expectedVersion);
218	    }
219	
220	    public void deleteDraftSegments(String channelId, LocalDate businessDay) {
221	        jdbc.update("DELETE FROM playout_draft_segment WHERE channel_id = ? AND business_day = ?",
222	                channelId, Date.valueOf(businessDay));
223	    }
224	
225	    public void insertDraftSegment(String id, String channelId, LocalDate businessDay,
226	                                   String assetId, long startMs, long endMs) {
227	        jdbc.update("INSERT INTO playout_draft_segment"
228	                        + " (id, channel_id, business_day, asset_id, start_ms, end_ms)"
229	                        + " VALUES (?, ?, ?, ?, ?, ?)",
230	                id, channelId, Date.valueOf(businessDay), assetId, startMs, endMs);
231	    }
232	
233	    public List<SegmentRow> findDraftSegments(String channelId, LocalDate businessDay) {
234	        return jdbc.query("SELECT id, asset_id, start_ms, end_ms FROM playout_draft_segment"
235	                        + " WHERE channel_id = ? AND business_day = ? ORDER BY start_ms, id",
236	                SEGMENT_MAPPER, channelId, Date.valueOf(businessDay));
237	    }
238	
239	    // ---------- 发布快照 ----------
240	
241	    /** 当前发布版本，无发布记录时为 0。 */
242	    public long currentPublishedVersion(String channelId, LocalDate businessDay) {
243	        Long version = jdbc.queryForObject(
244	                "SELECT MAX(published_version) FROM playout_publication"
245	                        + " WHERE channel_id = ? AND business_day = ?",
246	                Long.class, channelId, Date.valueOf(businessDay));
247	        return version == null ? 0L : version;
248	    }
249	
250	    public long insertPublication(String channelId, LocalDate businessDay, long publishedVersion,
251	                                  long draftVersion, long createdAtMs) {
252	        KeyHolder keyHolder = new GeneratedKeyHolder();
253	        jdbc.update(con -> {
254	            PreparedStatement ps = con.prepareStatement(
255	                    "INSERT INTO playout_publication"
256	                            + " (channel_id, business_day, published_version, draft_version, created_at_ms)"
257	                            + " VALUES (?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
258	            ps.setString(1, channelId);
259	            ps.setDate(2, Date.valueOf(businessDay));
260	            ps.setLong(3, publishedVersion);
261	            ps.setLong(4, draftVersion);
262	            ps.setLong(5, createdAtMs);
263	            return ps;
264	        }, keyHolder);
265	        return keyHolder.getKey().longValue();
266	    }
267	
268	    public void insertPublicationSegment(long publicationId, String segmentId, String assetId,
269	                                         long grantId, long startMs, long endMs) {
270	        jdbc.update("INSERT INTO playout_publication_segment"
271	                        + " (publication_id, segment_id, asset_id, grant_id, start_ms, end_ms)"
272	                        + " VALUES (?, ?, ?, ?, ?, ?)",
273	                publicationId, segmentId, assetId, grantId, startMs, endMs);
274	    }
275	
276	    /** 最新一次发布快照。 */
277	    public Optional<PublicationRow> findLatestPublication(String channelId, LocalDate businessDay) {
278	        return jdbc.query("SELECT id, channel_id, business_day, published_version, draft_version"
279	                        + " FROM playout_publication"
280	                        + " WHERE channel_id = ? AND business_day = ?"
281	                        + " ORDER BY published_version DESC LIMIT 1",
282	                PUBLICATION_MAPPER, channelId, Date.valueOf(businessDay)).stream().findFirst();
283	    }
284	
285	    /** 快照中覆盖指定时刻的片段（start <= at < end）。 */
286	    public Optional<PublicationSegmentRow> findPublicationSegmentAt(long publicationId, long atMs) {
287	        return jdbc.query("SELECT id, publication_id, segment_id, asset_id, grant_id, start_ms, end_ms"
288	                        + " FROM playout_publication_segment"
289	                        + " WHERE publication_id = ? AND start_ms <= ? AND end_ms > ?"
290	                        + " ORDER BY start_ms LIMIT 1",
291	                PUBLICATION_SEGMENT_MAPPER, publicationId, atMs, atMs).stream().findFirst();
292	    }
293	
294	    // ---------- 幂等请求记录 ----------
295	
296	    /** 按请求 ID 查询并加行锁，用于去重判定。 */
297	    public Optional<RequestRow> findRequestForUpdate(String requestId) {
298	        return jdbc.query("SELECT request_id, operation, params_hash, response_body"
299	                        + " FROM playout_request WHERE request_id = ? FOR UPDATE",
300	                REQUEST_MAPPER, requestId).stream().findFirst();
301	    }
302	
303	    public void insertRequest(String requestId, String operation, String paramsHash, long createdAtMs) {
304	        jdbc.update("INSERT INTO playout_request (request_id, operation, params_hash, created_at_ms)"
305	                + " VALUES (?, ?, ?, ?)", requestId, operation, paramsHash, createdAtMs);
306	    }
307	
308	    public void completeRequest(String requestId, String responseBody) {
309	        jdbc.update("UPDATE playout_request SET response_body = ? WHERE request_id = ?",
310	                responseBody, requestId);
311	    }
312	
313	    /** 判断是否为唯一键冲突（草稿首建、发布版本、请求 ID 等并发场景）。 */
314	    public static boolean isDuplicateKey(RuntimeException ex) {
315	        return ex instanceof DuplicateKeyException;
316	    }
317	
318	    // ---------- 紧急插播 ----------
319	
320	    public void insertOverride(String overrideKey, String channelId, String assetId, long grantId,
321	                               int priority, long startMs, long endMs, LocalDate businessDay,
322	                               long createdAtMs) {
323	        jdbc.update("INSERT INTO playout_emergency_override"
324	                        + " (override_key, channel_id, asset_id, grant_id, priority, start_ms, end_ms,"
325	                        + "  business_day, status, created_at_ms)"
326	                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'ACTIVE', ?)",
327	                overrideKey, channelId, assetId, grantId, priority, startMs, endMs,
328	                Date.valueOf(businessDay), createdAtMs);
329	    }
330	
331	    public Optional<OverrideRow> findOverride(String overrideKey) {
332	        return jdbc.query("SELECT override_key, channel_id, asset_id, grant_id, priority, start_ms,"
333	                        + " end_ms, business_day, status, cancel_request_id, cancelled_at_ms, created_at_ms"
334	                        + " FROM playout_emergency_override WHERE override_key = ?",
335	                OVERRIDE_MAPPER, overrideKey).stream().findFirst();
336	    }
337	
338	    /** 按全局键查询并加行锁。 */
339	    public Optional<OverrideRow> findOverrideForUpdate(String overrideKey) {
340	        return jdbc.query("SELECT override_key, channel_id, asset_id, grant_id, priority, start_ms,"
341	                        + " end_ms, business_day, status, cancel_request_id, cancelled_at_ms, created_at_ms"
342	                        + " FROM playout_emergency_override WHERE override_key = ? FOR UPDATE",
343	                OVERRIDE_MAPPER, overrideKey).stream().findFirst();
344	    }
345	
346	    /** 锁定频道行，串行化同频道的插播创建/取消，避免并发区间漏判（H2 无间隙锁，MySQL 下同样安全）。 */
347	    public void lockChannelForUpdate(String channelId) {
348	        jdbc.queryForList("SELECT id FROM playout_channel WHERE id = ? FOR UPDATE", channelId);
349	    }
350	
351	    /**
352	     * 同频道、同优先级、状态 ACTIVE 且与 [startMs, endMs) 相交的插播（区间左闭右开：
353	     * 相邻 start == end 不算相交）。须在持频道锁后调用。
354	     */
355	    public List<OverrideRow> findActiveOverlappingForUpdate(String channelId, int priority,
356	                                                            long startMs, long endMs) {
357	        return jdbc.query("SELECT override_key, channel_id, asset_id, grant_id, priority, start_ms,"
358	                        + " end_ms, business_day, status, cancel_request_id, cancelled_at_ms, created_at_ms"
359	                        + " FROM playout_emergency_override"
360	                        + " WHERE channel_id = ? AND status = 'ACTIVE' AND priority = ?"
361	                        + " AND start_ms < ? AND end_ms > ?"
362	                        + " ORDER BY start_ms, override_key FOR UPDATE",
363	                OVERRIDE_MAPPER, channelId, priority, endMs, startMs);
364	    }
365	
366	    /** 命中某时刻的 ACTIVE 插播，按优先级从高到低排序（同级区间不重叠，排序结果确定）。 */
367	    public List<OverrideRow> findActiveOverridesAt(String channelId, long atMs) {
368	        return jdbc.query("SELECT override_key, channel_id, asset_id, grant_id, priority, start_ms,"
369	                        + " end_ms, business_day, status, cancel_request_id, cancelled_at_ms, created_at_ms"
370	                        + " FROM playout_emergency_override"
371	                        + " WHERE channel_id = ? AND status = 'ACTIVE'"
372	                        + " AND start_ms <= ? AND end_ms > ?"
373	                        + " ORDER BY priority DESC, start_ms ASC, override_key ASC",
374	                OVERRIDE_MAPPER, channelId, atMs, atMs);
375	    }
376	
377	    /** 取消插播；返回受影响行数，0 表示不存在或已取消。 */
378	    public int cancelOverride(String overrideKey, String cancelRequestId, long cancelledAtMs) {
379	        return jdbc.update("UPDATE playout_emergency_override"
380	                        + " SET status = 'CANCELLED', cancel_request_id = ?, cancelled_at_ms = ?"
381	                        + " WHERE override_key = ? AND status = 'ACTIVE'",
382	                cancelRequestId, cancelledAtMs, overrideKey);
383	    }
384	}
