291	    /**
292	     * 选取某时刻生效的最高优先级紧急插播：候选为区间命中且 ACTIVE 的插播，按优先级降序，
293	     * 跳过其指定授权已撤销的插播。授权状态为查询时的实时状态。
294	     */
295	    private Optional<OverrideRow> selectActiveOverrideAt(String channelId, long atMs) {
296	        for (OverrideRow candidate : repo.findActiveOverridesAt(channelId, atMs)) {
297	            GrantRow grant = repo.findGrant(candidate.grantId()).orElse(null);
298	            if (grant != null && !grant.revoked()) {
299	                return Optional.of(candidate);
300	            }
301	        }
302	        return Optional.empty();
303	    }
