414	    /** 查询紧急插播明细（不做状态校验，ACTIVE/CANCELLED 均返回，含取消情况与原授权关联）。 */
415	    @Transactional(readOnly = true)
416	    public EmergencyOverrideResponse getEmergencyOverride(String overrideKey) {
417	        OverrideRow row = repo.findOverride(overrideKey)
418	                .orElseThrow(() -> ApiException.notFound("紧急插播不存在: " + overrideKey));
419	        return toOverrideResponse(row);
420	    }
