private DecisionSnapshot computeDecisionLocked(ChannelRow channel, String channelId, long atMs) {
    // 紧急插播：锁定授权行逐一判定，撤销与本登记按提交顺序串行
    for (OverrideRow candidate : repo.findActiveOverridesAt(channelId, atMs)) {
        GrantRow grant = repo.findGrantForUpdate(candidate.grantId()).orElse(null);
        if (grant != null && !grant.revoked()) {
            return new DecisionSnapshot(candidate.assetId(), DecisionSource.EMERGENCY, null,
                    candidate.overrideKey(), null, null, null, candidate.grantId());
        }
    }
    LocalDate businessDay = ... atMs in ZONE;
    Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
    if (publication.isEmpty()) return fallback snapshot NO_PUBLISHED_SCHEDULE;
    Optional<PublicationSegmentRow> segment = repo.findPublicationSegmentAt(publication.get().id(), atMs);
    if (segment.isEmpty()) return GAP fallback;
    PublicationSegmentRow hit = segment.get();
    GrantRow grant = repo.findGrantForUpdate(hit.grantId()).orElseThrow(SNAPSHOT_INCOMPLETE);
    if (grant.revoked()) return fallback GRANT_REVOKED with publicationId+segmentId;
    return PROGRAM snapshot with publicationId, publishedVersion, segmentId, grantId.
}
