@Transactional
public PlayReceiptResponse submitReceipt(String playKey, SubmitReceiptRequest request) {
    String hash = sha256(OP_SUBMIT_RECEIPT + "|" + playKey + "|" + request.result() + "|" + request.note());
    return idempotent(request.requestId(), OP_SUBMIT_RECEIPT, hash, PlayReceiptResponse.class,
        () -> doSubmitReceipt(playKey, request));
}

private PlayReceiptResponse doSubmitReceipt(String playKey, SubmitReceiptRequest request) {
    repo.findPlayDecision(playKey).orElseThrow(() -> ApiException.notFound("播出决定不存在: " + playKey));
    long receiptAtMs = nowMs();
    try {
        repo.insertReceipt(playKey, request.result().name(), request.note().trim(), request.requestId(), receiptAtMs);
    } catch (DuplicateKeyException e) {
        ReceiptRow existing = repo.findReceiptForUpdate(playKey).orElseThrow(...);
        return reconcileReceipt(playKey, existing, request);
    }
    return new PlayReceiptResponse(playKey, request.result(), note, request.requestId(), atMs(receiptAtMs));
}
