        // 404：频道不存在 / 决定不存在 / 列表频道不存在
        register(ctx, "v-4", "pk-x", T_1030); // 频道未建？不，ctx 频道已建；用 ghost 频道
        postJson("/api/play-decisions",
                        registerBody("v-5", ctx.key("pk-g"), ctx.prefix + "ghost", T_1030))
